#nullable enable // autogenerated

using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.UI;

namespace MVZ2Logic.UI
{
    [DisallowMultipleComponent]
    [RequireComponent(typeof(Selectable))]
    public class SelectableResolver : MonoBehaviour, ISpriteResolver
    {
        private void OnEnable()
        {
            UpdateResolver();
        }
        private void OnDisable()
        {
            ResetResolver();
        }
        public void UpdateResolver()
        {
            if (!spriteChanged)
            {
                spriteChanged = true;
                BaseSpriteState = Selectable.spriteState;
            }
            SetSpriteStateForced(BaseSpriteState);
        }
        public void SetSpriteState(SpriteState sprite)
        {
            if (sprite.Equals(BaseSpriteState))
                return;
            SetSpriteStateForced(sprite);
        }
        public void SetSpriteStateForced(SpriteState spriteState)
        {
            var final = spriteState;
            if (Global.Resources != null)
            {
                final.selectedSprite = GetFinalSprite(final.selectedSprite);
                final.disabledSprite = GetFinalSprite(final.disabledSprite);
                final.pressedSprite = GetFinalSprite(final.pressedSprite);
                final.highlightedSprite = GetFinalSprite(final.highlightedSprite);
            }
            spriteChanged = true;
            BaseSpriteState = spriteState;
            Selectable.spriteState = final;
        }
        public void ResetResolver()
        {
            if (spriteChanged)
            {
                spriteChanged = false;
                Selectable.spriteState = BaseSpriteState;
                BaseSpriteState = default;
            }
        }
        public virtual SpriteState GetSpriteState()
        {
            return Selectable.spriteState;
        }
        private Sprite? GetFinalSprite(Sprite? sprite)
        {
            if (!sprite.Exists() || Global.Resources == null)
                return null;
            return Global.Resources.GetFinalSprite(sprite);
        }
        public SpriteState BaseSpriteState { get; private set; }
        public Selectable Selectable
        {
            get
            {
                if (!_selectable.Exists())
                {
                    _selectable = GetComponent<Selectable>();
                }
                return _selectable;
            }
        }
        private Selectable? _selectable;
        private bool spriteChanged;
    }

}
